 statuses={'qualified_route_gated_screenline':'具备路由编号/名称证据的候选断面','held_no_unique_observation_section':'观测区间不能唯一确定','held_multiple_relative_levels':'对应多个相对层级','held_more_than_two_parallel_or_branching_roads':'截到过多平行/分支道路','held_no_geometry_class_candidate':'无满足几何/道路类别的候选','held_cut_at_source_segment_endpoint':'截面过近源线段端点','held_geometry_only_no_route_evidence':'仅几何匹配，无路线证据'}
 statusrows=''.join(f'<tr><td>{statuses.get(k,k)}</td><td>{n}</td></tr>'for k,n in match['statuses'].items())
 ledgerlabels={'routed_at_least_one_local_representative':'至少一端为路网内分区，实际分配','held_local_same_representative':'本地同接入点，暂留（含区内行程）','conditional_remote_through':'远端—远端条件性穿越，仅补充分支','outside_remote_same_portal':'远端同门户，未分配','outside_remote_other':'其他远端—远端，未分配'}
